// codemap/query.mjs: look things up in this folder's graph.json. Generated by build.mjs; the Claude
// Code CLI calls it when you ask questions from the map (node codemap/serve.mjs).
//
// usage: node codemap/query.mjs overview
//        node codemap/query.mjs find "<words>" [--kind module|file|endpoint|symbol] [--limit 15]
//        node codemap/query.mjs show <id>
//        node codemap/query.mjs path <fromId> <toId>
//        node codemap/query.mjs context "<task>" [--budget 6000] [--json]   what to read for a task, as line ranges
//        node codemap/query.mjs map [--budget 1500]                           the codebase in ~1,500 tokens
//        node codemap/query.mjs fn <name | file#name>                         where a function is, its callers and callees
//        node codemap/query.mjs trace "<screen | METHOD /path | file#fn | words>" [--depth 8] [--mermaid | --save "<title>"]
//        node codemap/query.mjs impact [--base <git ref>] [--files a,b] [--markdown]   what a change touches
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { execFileSync } from 'node:child_process';

const here = path.dirname(fileURLToPath(import.meta.url));
const G = JSON.parse(fs.readFileSync(path.join(here, 'graph.json'), 'utf8'));
const q = createGraphQuery(G);
const argv = process.argv.slice(2);
const flag = (name) => { const i = argv.indexOf('--' + name); if (i < 0) return undefined; const v = argv[i + 1]; argv.splice(i, 2); return v; };
const kind = flag('kind'), limit = flag('limit'), budget = flag('budget');
const bool = (name) => { const i = argv.indexOf('--' + name); if (i < 0) return false; argv.splice(i, 1); return true; };
const asJson = bool('json'), mermaid = bool('mermaid'), markdown = bool('markdown');
const brief = bool('brief');
const depth = flag('depth'), base = flag('base'), only = flag('files'), save = flag('save');
const root = path.join(here, '..');
const [cmd, ...rest] = argv;
// a file edited after the map was built: its line ranges may have moved, so say so
const builtAt = Date.parse(G.meta?.generatedAt || 0);
const fresh = (p) => { try { return fs.statSync(path.join(here, '..', p)).mtimeMs > builtAt + 1000; } catch { return false; } };
try {
  let out;
  if (cmd === 'context') {
    const c = q.context(rest.join(' '), Number(budget) || 6000, fresh);
    if (asJson || !c.found) { console.log(JSON.stringify(c, null, 1)); process.exit(0); }
    if (brief) {
      // a ready brief for a subagent: what to read, what must keep working, how to check — instead of "go explore"
      const B = [`## Task\n${c.task}`];
      const R = [`## Read first (from the codebase map; ~${c.readTokens} tokens)`];
      for (const x of c.read) R.push(`- \`${x.file}\` lines ${x.ranges.map(([a, b, n]) => `${a}-${b}${n ? ` (${n})` : ''}`).join(', ')}: ${x.name}${x.what ? `, ${x.what}` : ''}${x.changedSinceMap ? ' [edited since the map: check line numbers]' : ''}`);
      B.push(R.join('\n'));
      const callers = [...new Set(c.read.flatMap((x) => x.calledBy || []))];
      if (callers.length) B.push(`## Keep these callers working\n${callers.map((x) => `- ${x}`).join('\n')}`);
      if (c.endpoints.length) B.push(`## Endpoints involved\n${c.endpoints.map((x) => `- ${x}`).join('\n')}`);
      if (c.tests.length) B.push(`## Tests to run or extend\n${c.tests.map((x) => `- ${x}`).join('\n')}`);
      B.push(`## How to work\n- Read the ranges above before anything else; open other files only if they are not enough.\n- \`node codemap/query.mjs fn <name>\` shows a function's callers and callees; \`trace\` follows a flow end to end.\n- Report back what you changed (files and functions) and anything you could not finish.`);
      console.log(B.join('\n\n'));
      process.exit(0);
    }
    const L = [`CONTEXT for "${c.task}": read these ${c.read.length} ranges (~${c.readTokens} tokens) instead of exploring (~${c.exploreTokens} tokens in those parts).`];
    c.read.forEach((x, i) => {
      // the path once, then its line ranges: fewer tokens than repeating it
      L.push(`${i + 1}. ${x.file}  ${x.ranges.map(([a, b, n]) => `${a}-${b}${n ? ` ${n}` : ''}`).join(', ')}${x.changedSinceMap ? '  (edited since the map: check line numbers)' : ''}`);
      L.push(`   ${x.name}${x.part ? ` [${x.part}]` : ''}${x.what ? `: ${x.what}` : ''}`);
      if (x.calledBy) L.push(`   called by ${x.calledBy.join(', ')}`);
      if (x.calls) L.push(`   calls ${x.calls.join(', ')}`);
    });
    if (c.endpoints.length) L.push(`Endpoints: ${c.endpoints.join(' | ')}`);
    if (c.screens.length) L.push(`Screens: ${c.screens.join(' | ')}`);
    if (c.tests.length) L.push(`Tests: ${c.tests.join(', ')}`);
    if (c.health.length) L.push(`Health: ${c.health.join(' | ')}`);
    L.push('More: fn <name> (callers/callees) · show <file> · find "<words>". The map can lag: confirm in the code before editing.');
    console.log(L.join('\n'));
    process.exit(0);
  }
  if (cmd === 'trace') {
    const r = traceReport(G, rest.join(' '), { depth, json: asJson, mermaid, save });
    if (r.error) { console.log(r.error); process.exit(1); }
    if (r.save) {
      const file = path.join(here, 'custom-flows.json');
      let data = { flows: [] };
      try { data = JSON.parse(fs.readFileSync(file, 'utf8')); } catch {}
      data.flows = [...(data.flows || []).filter((f) => f.id !== r.save.id), r.save];
      fs.writeFileSync(file, JSON.stringify(data, null, 2) + '\n');
    }
    console.log(r.out);
    process.exit(0);
  }
  if (cmd === 'impact') {
    const changed = new Set();
    if (only) for (const p of only.split(',').map((s) => s.trim()).filter(Boolean)) changed.add(p);
    else for (const r of G.meta?.repos?.length ? G.meta.repos : [{ path: '.' }]) {
      const abs = path.join(root, r.path), prefix = r.path === '.' ? '' : r.path + '/';
      const run = (a) => { try { return execFileSync('git', ['-C', abs, ...a], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] }); } catch { return ''; } };
      const lists = base ? [run(['diff', '--name-only', `${base}...HEAD`, '--', '.'])] : [run(['diff', '--name-only', 'HEAD', '--', '.']), run(['ls-files', '--others', '--exclude-standard', '--', '.'])];
      for (const out of lists) for (const p of out.split('\n').filter(Boolean)) changed.add(prefix + p);
    }
    console.log(impactReport(G, changed, { depth, base, json: asJson, markdown }).out);
    process.exit(0);
  }
  if (cmd === 'delta') {
    const snapDir = path.join(here, '.cache', 'snapshots');
    const snaps = fs.existsSync(snapDir) ? fs.readdirSync(snapDir).filter((x) => x.startsWith('graph-')).sort() : [];
    const pick = rest[0] ? path.resolve(rest[0]) : snaps.length ? path.join(snapDir, snaps[snaps.length - 1]) : null;
    if (!pick) { console.log('No earlier map to compare with yet: the next update of the codemap keeps one.'); process.exit(0); }
    console.log(deltaReport(JSON.parse(fs.readFileSync(pick, 'utf8')), G, { json: asJson }).out);
    process.exit(0);
  }
  if (cmd === 'layers') { console.log(asJson ? JSON.stringify(layersReport(G).layers) : layersReport(G).out); process.exit(0); }
  if (cmd === 'erd') { console.log(erdReport(G, { json: asJson, mermaid }).out); process.exit(0); }
  if (cmd === 'map') { console.log(q.repoMap(Number(budget) || 1500)); process.exit(0); }
  if (cmd === 'fn') out = q.fn(rest.join(' '));
  else if (cmd === 'overview') out = q.overview();
  else if (cmd === 'find') out = q.find(rest.join(' '), kind, limit);
  else if (cmd === 'show') out = q.show(rest[0]);
  else if (cmd === 'path') out = q.path(rest[0], rest[1]);
  else { console.log('commands: delta [older graph.json] | layers | erd [--mermaid] | trace "<start>" | impact [--base ref] | context "<task>" [--budget N] | map [--budget N] | fn <name|file#name> | overview | find "<words>" [--kind module|file|endpoint|symbol] | show <id> | path <fromId> <toId>'); process.exit(cmd ? 1 : 0); }
  console.log(JSON.stringify(out));
} catch (e) {
  console.log(JSON.stringify({ error: e.message }));
  process.exit(1);
}
